let releases = openReleases()
function openReleases() {
  const source = new EventSource('/.tachyon/topics/releases')
  source.onmessage = (event) => console.log(event.lastEventId, JSON.parse(event.data))
  source.addEventListener('topic-error', (event) => {
    const failure = JSON.parse(event.data)
    if (failure.terminal) source.close()
    if (failure.code === 'TY_TOPIC_CURSOR_STALE') releases = openReleases()
  })
  return source
}

